import base64
import hashlib
import os
import secrets
import time
import urllib.parse
import webbrowser
from http.server import BaseHTTPRequestHandler, HTTPServer
from typing import Dict, Optional

import requests


class Auth0PKCELoginFlow:
    def __init__(
        self,
        domain: Optional[str] = None,
        client_id: Optional[str] = None,
        redirect_host: str = "127.0.0.1",
        redirect_port: int = 8765,
        redirect_path: str = "/callback",
        scope: str = "openid profile email",
        audience: Optional[str] = None,
        timeout_seconds: int = 300,
    ) -> None:
        self.domain = (domain or os.environ["AUTH0_DOMAIN"]).strip()
        self.client_id = (client_id or os.environ["AUTH0_CLIENT_ID"]).strip()
        self.redirect_host = redirect_host
        self.redirect_port = redirect_port
        self.redirect_path = redirect_path
        self.scope = scope
        self.audience = audience
        self.timeout_seconds = timeout_seconds
        self.redirect_uri = f"http://{self.redirect_host}:{self.redirect_port}{self.redirect_path}"

    @staticmethod
    def _base64url(data: bytes) -> str:
        return base64.urlsafe_b64encode(data).rstrip(b"=").decode("ascii")

    @staticmethod
    def _generate_code_verifier() -> str:
        return secrets.token_urlsafe(64)[:128]

    def _generate_pkce_pair(self) -> Dict[str, str]:
        code_verifier = self._generate_code_verifier()
        digest = hashlib.sha256(code_verifier.encode("ascii")).digest()
        code_challenge = self._base64url(digest)
        return {
            "code_verifier": code_verifier,
            "code_challenge": code_challenge,
            "code_challenge_method": "S256",
        }

    @staticmethod
    def _generate_state() -> str:
        return secrets.token_urlsafe(32)

    @staticmethod
    def _generate_nonce() -> str:
        return secrets.token_urlsafe(32)

    def build_authorization_url(
        self,
        state: str,
        nonce: str,
        code_challenge: str,
        connection: Optional[str] = None,
        organization: Optional[str] = None,
        prompt: Optional[str] = None,
    ) -> str:
        params = {
            "response_type": "code",
            "client_id": self.client_id,
            "redirect_uri": self.redirect_uri,
            "scope": self.scope,
            "state": state,
            "nonce": nonce,
            "code_challenge": code_challenge,
            "code_challenge_method": "S256",
        }
        if self.audience:
            params["audience"] = self.audience
        if connection:
            params["connection"] = connection
        if organization:
            params["organization"] = organization
        if prompt:
            params["prompt"] = prompt
        return f"https://{self.domain}/authorize?{urllib.parse.urlencode(params)}"

    def _wait_for_callback(self, expected_state: str) -> Dict[str, str]:
        result: Dict[str, str] = {}

        class CallbackHandler(BaseHTTPRequestHandler):
            def do_GET(self) -> None:
                parsed = urllib.parse.urlparse(self.path)
                if parsed.path != self.server.redirect_path:
                    self.send_response(404)
                    self.end_headers()
                    self.wfile.write(b"Not Found")
                    return

                query = urllib.parse.parse_qs(parsed.query)
                result["state"] = query.get("state", [""])[0]
                result["code"] = query.get("code", [""])[0]
                result["error"] = query.get("error", [""])[0]
                result["error_description"] = query.get("error_description", [""])[0]

                if result["error"]:
                    self.send_response(400)
                    self.send_header("Content-Type", "text/html; charset=utf-8")
                    self.end_headers()
                    self.wfile.write(
                        f"<html><body><h1>Login failed</h1><p>{result['error']}: {result['error_description']}</p></body></html>".encode(
                            "utf-8"
                        )
                    )
                elif result["state"] != expected_state:
                    self.send_response(400)
                    self.send_header("Content-Type", "text/html; charset=utf-8")
                    self.end_headers()
                    self.wfile.write(
                        b"<html><body><h1>Invalid state</h1><p>State verification failed.</p></body></html>"
                    )
                else:
                    self.send_response(200)
                    self.send_header("Content-Type", "text/html; charset=utf-8")
                    self.end_headers()
                    self.wfile.write(
                        b"<html><body><h1>Login complete</h1><p>You may close this window.</p></body></html>"
                    )

            def log_message(self, format: str, *args) -> None:
                return

        server = HTTPServer((self.redirect_host, self.redirect_port), CallbackHandler)
        server.redirect_path = self.redirect_path
        server.timeout = 1

        deadline = time.time() + self.timeout_seconds
        try:
            while time.time() < deadline and "code" not in result and "error" not in result:
                server.handle_request()
        finally:
            server.server_close()

        if not result:
            raise TimeoutError("Timed out waiting for the Auth0 redirect callback.")
        if result.get("error"):
            raise RuntimeError(
                f"Auth0 authorization failed: {result.get('error')} {result.get('error_description', '')}".strip()
            )
        if result.get("state") != expected_state:
            raise RuntimeError("State mismatch in Auth0 redirect callback.")
        if not result.get("code"):
            raise RuntimeError("Missing authorization code in Auth0 redirect callback.")
        return result

    def exchange_code_for_tokens(self, code: str, code_verifier: str) -> Dict:
        token_url = f"https://{self.domain}/oauth/token"
        payload = {
            "grant_type": "authorization_code",
            "client_id": self.client_id,
            "code": code,
            "redirect_uri": self.redirect_uri,
            "code_verifier": code_verifier,
        }
        response = requests.post(
            token_url,
            headers={"Content-Type": "application/x-www-form-urlencoded"},
            data=payload,
            timeout=30,
        )
        response.raise_for_status()
        return response.json()

    def fetch_userinfo(self, access_token: str) -> Dict:
        response = requests.get(
            f"https://{self.domain}/userinfo",
            headers={"Authorization": f"Bearer {access_token}"},
            timeout=30,
        )
        response.raise_for_status()
        return response.json()

    def login(
        self,
        open_browser: bool = True,
        connection: Optional[str] = None,
        organization: Optional[str] = None,
        prompt: Optional[str] = None,
    ) -> Dict:
        pkce = self._generate_pkce_pair()
        state = self._generate_state()
        nonce = self._generate_nonce()

        authorization_url = self.build_authorization_url(
            state=state,
            nonce=nonce,
            code_challenge=pkce["code_challenge"],
            connection=connection,
            organization=organization,
            prompt=prompt,
        )

        if open_browser:
            webbrowser.open(authorization_url, new=1, autoraise=True)

        callback = self._wait_for_callback(expected_state=state)
        tokens = self.exchange_code_for_tokens(
            code=callback["code"],
            code_verifier=pkce["code_verifier"],
        )

        result = {
            "authorization_url": authorization_url,
            "token_response": tokens,
        }

        access_token = tokens.get("access_token")
        if access_token:
            try:
                result["userinfo"] = self.fetch_userinfo(access_token)
            except requests.RequestException:
                result["userinfo"] = None

        return result
